package com.example.it_canteen;
import android.os.Bundle; import android.widget.Button; import android.widget.Toast; import android.widget.PopupMenu; import androidx.appcompat.app.AppCompatActivity;
public class details extends AppCompatActivity { Button submitPayment,paymentoptions; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.details);submitPayment=findViewById(R.id.btn_finalsubmit);paymentoptions=findViewById(R.id.btn_payment);paymentoptions.setOnClickListener(v->{PopupMenu p=new PopupMenu(this,paymentoptions);p.getMenuInflater().inflate(R.menu.payment_popup,p.getMenu());p.setOnMenuItemClickListener(item->{if(item.getItemId()==R.id.cardpay)Toast.makeText(this,"You selected card",Toast.LENGTH_SHORT).show();else if(item.getItemId()==R.id.netbanking)Toast.makeText(this,"You selected netbanking",Toast.LENGTH_SHORT).show();else Toast.makeText(this,"You selected cash on delivery",Toast.LENGTH_SHORT).show();return true;});p.show();});submitPayment.setOnClickListener(v->Toast.makeText(this,"Your Order is Registered",Toast.LENGTH_SHORT).show());} }
